// The first plan of a class is the spec that carries itself while levelling.
static constexpr CoaTalentPlan const* GetCoaTalentPlan(uint8_t classId)
{
    for (CoaTalentPlan const& p : CoaTalentPlans)
        if (p.classId == classId)
            return &p;

    return nullptr;
}

static constexpr CoaTalentPlan const* GetCoaTalentPlanForSpec(uint8_t classId,
                                                              uint16_t specId)
{
    for (CoaTalentPlan const& p : CoaTalentPlans)
        if (p.classId == classId && p.specId == specId)
            return &p;

    return nullptr;
}

static constexpr uint16_t CoaTalentPlanCount(uint8_t classId)
{
    uint16_t n = 0;
    for (CoaTalentPlan const& p : CoaTalentPlans)
        if (p.classId == classId)
            ++n;

    return n;
}

static constexpr CoaTalentPlan const* GetCoaTalentPlanByIndex(uint8_t classId,
                                                              uint16_t index)
{
    for (CoaTalentPlan const& p : CoaTalentPlans)
        if (p.classId == classId && !index--)
            return &p;

    return nullptr;
}

// Points per level: one per level from 10 on, the first into the class tree.
static constexpr uint16_t CoaClassTreePoints(uint8_t level)
{
    return level < 10 ? 0 : uint16_t((level - 9 + 1) / 2);
}

static constexpr uint16_t CoaSpecTreePoints(uint8_t level)
{
    return level < 10 ? 0 : uint16_t((level - 9) / 2);
}

